import{_ as o,o as t,c as d,ag as s}from"./chunks/framework.BaNuf0sO.js";const A=JSON.parse('{"title":"components 组件族总引导","description":"","frontmatter":{},"headers":[],"relativePath":"docs/agent/src/components/README.md","filePath":"docs/agent/src/components/README.md"}'),r={name:"docs/agent/src/components/README.md"};function a(i,e,n,c,l,g){return t(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="components-组件族总引导" tabindex="-1">components 组件族总引导 <a class="header-anchor" href="#components-组件族总引导" aria-label="Permalink to &quot;components 组件族总引导&quot;">​</a></h1><p>agent 共 6 个组件族，公开组件全部经顶层 barrel 导出（<code>import { AiDialogue } from &quot;@done-coding/forge-agent&quot;</code>）。各族目录内均有 <code>README.md</code> 入口（组件清单 + 指向 <code>docs/</code> 组件详情文档，<code>README-&lt;PascalName&gt;.md</code>）。</p><p><strong>页面范式</strong>：<code>AiConfigProvider</code>（主题 + expose 通道根）→ 对话主件（<code>AiDialogue</code> 全流程 / <code>AiMessageList</code> 受控展示 / <code>AiDialogueWrap</code> 浮层 / <code>AiDialogueGroup</code> 多会话）→ 内部件（bubble / sender 扩展 / operation 操作条）由主件自动装配。</p><h2 id="对话组件契约-接入决策" tabindex="-1">对话组件契约（接入决策） <a class="header-anchor" href="#对话组件契约-接入决策" aria-label="Permalink to &quot;对话组件契约（接入决策）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>一等公民（优先用）</th><th>说明</th></tr></thead><tbody><tr><td>接入最快 · 零后端</td><td><code>AiMessageList</code></td><td>受控消息展示（`{id,role,parts</td></tr><tr><td>完整对话 · 自管全流程</td><td><code>AiDialogue</code></td><td>持久化（IndexedDB）+ SSE + 输入 + 流式渲染一揽子；需 SSE 端点</td></tr><tr><td>多会话 + 会话列表</td><td><code>AiDialogueGroup</code></td><td>AiDialogue + 操作条（折叠式会话记录）</td></tr><tr><td>浮层挂载</td><td><code>AiDialogueWrap</code></td><td>Teleport fixed 面板（拉手开合 + 移动端全屏），内嵌上述主件</td></tr></tbody></table><ul><li>受控路径（AiMessageList + AiSender）与自管路径（AiDialogue）<strong>可独立使用</strong>：受控路径不碰 IndexedDB / SSE，消费方自己持有消息列表；自管路径由平台接管全部流程。</li><li><strong>expose 通道</strong>：<code>AiConfigProvider</code> provide 全局 expose（sender/bubbleList/ask/sessionOperate/sessionExposeMap），消费方经 <code>useAiExposeInject</code> 取（子树外用 <code>AiConfigProvider</code> 的 <code>defineExpose</code>）——如外部「快捷提问」按钮调 <code>aiExpose.ask({ value })</code>，或 <code>ask({ parts })</code> <strong>以用户名义</strong>发一张结构化数据卡（<code>#part</code> 槽对用户气泡同样生效）。</li><li>[MUST NOT] 在 <code>AiConfigProvider</code> <strong>外层</strong>再自建 provider：会被内层遮蔽（注册表恒空、<code>ask</code> 恒 undefined），检测到即 <code>console.warn</code>。</li><li><strong>协议层</strong>：AiDialogue 的 SSE 链路为 <strong>OpenAI Chat Completions 协议</strong>——入站经 <code>sseConverter</code>（帧 → parts）、出站经 <code>sseMessagesSerializer</code>（parts → wire，默认 <code>toOpenAIMessages</code>），两者成对，见包级 README「协议契约」节。AiMessageList / AiSender 为受控原语，<strong>零协议耦合</strong>。</li></ul><h2 id="族清单" tabindex="-1">族清单 <a class="header-anchor" href="#族清单" aria-label="Permalink to &quot;族清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>族</th><th>组件</th><th>入口</th></tr></thead><tbody><tr><td>dialogue 对话族</td><td>AiDialogue / AiDialogueGroup / AiDialogueWrap / AiMessageList（全公开）</td><td><a href="/done-coding-showcase/docs/agent/src/components/dialogue/README.html">README</a></td></tr><tr><td>sender 输入族</td><td>AiSender（公开）；AiSenderHeader（内部件）</td><td><a href="/done-coding-showcase/docs/agent/src/components/sender/README.html">README</a></td></tr><tr><td>config 配置族</td><td>AiConfigProvider（公开）</td><td><a href="/done-coding-showcase/docs/agent/src/components/config/README.html">README</a></td></tr><tr><td>operation 操作族</td><td>AiOperationBar / AiOperationBtns（内部件，AiDialogueGroup 装配）</td><td><a href="/done-coding-showcase/docs/agent/src/components/operation/README.html">README</a></td></tr><tr><td>bubble 气泡族</td><td>AiBubbleContent / AiBubbleFooter / AiCodeHeaderControl / AiContentSplit / AiThinkBox / AiTypewriter（内部件）</td><td><a href="/done-coding-showcase/docs/agent/src/components/bubble/README.html">README</a></td></tr><tr><td>json-trigger 结构化输出族</td><td>LlmJsonTrigger（公开；配套纯方法 getJsonFromLlm）——schema in → JSON out，与消费方 duck 契约互盲对接</td><td><a href="/done-coding-showcase/docs/agent/src/components/json-trigger/README.html">README</a></td></tr></tbody></table><h2 id="写作与维护约定" tabindex="-1">写作与维护约定 <a class="header-anchor" href="#写作与维护约定" aria-label="Permalink to &quot;写作与维护约定&quot;">​</a></h2><ul><li>各族 <code>README.md</code> = 入口（组件清单 + 一句话），组件详情在 <code>docs/README-&lt;PascalName&gt;.md</code></li><li><strong>快速上手 = 最小可用形态</strong>（默认值即够用，5–20 行可直接抄的代码）——[MUST NOT] 把能力全开示例当快速上手</li><li><strong>每篇必含「能力边界 / 按需使用」段</strong>（快速上手之后）：逐条断言「默认关/默认即够用 + 仅当 X 场景才开（判据）」</li><li>API 段以 <code>src/types/index.ts</code> + 组件源码为真相源；与文档冲突时以源码为准</li><li>内部件（不导出）也写独立文档，但<strong>仅 API 段</strong>（props/emits/slots/expose + 机制契约，以源码为真相源）——[MUST NOT] 写定位 / 快速上手等消费向叙事段（无对外使用场景，写了反而误导 AI 当公共组件用）；族入口标注「内部件 · 仅 API」</li><li>新增/改造对外组件 [MUST] 同步补 <code>docs/README-&lt;PascalName&gt;.md</code>（随 <code>docs/specs/</code> 任务闭环）</li></ul><h3 id="开发流程-api-契约先行" tabindex="-1">开发流程（API 契约先行） <a class="header-anchor" href="#开发流程-api-契约先行" aria-label="Permalink to &quot;开发流程（API 契约先行）&quot;">​</a></h3><p>新组件 / 组件改造（含 API 变更）[MUST] 按四步走，[MUST NOT] 先实现后补文档：</p><ol><li><strong>API 契约先行</strong>：先写 <code>types.ts</code>（props/emits 类型）并<strong>同步更新</strong>对应 <code>docs/README-&lt;PascalName&gt;.md</code> 的 API 段——API 表先于实现存在、锁定契约</li><li><strong>实现</strong>：满足契约；实现中 API 微调属正常，同步回改 API 表</li><li><strong>验收</strong>：demo（demo-src/demos/）+ 单测 + build（规则 9.1 双链）</li><li><strong>非 API 文档收尾</strong>（[MUST] 作为 spec TASK 单列）：定位 / 快速上手（最小可用）/ 能力边界 / 反模式——此时实现与 demo 已定型，写出的姿势全部经实证</li></ol><p><strong>复核闸</strong>：第 4 步执行时 [MUST] 对照 <code>types.ts</code> + <code>withDefaults</code> 复核 API 表——「API 以 types.ts 为真相源」双向执行：实现前 API 表当契约写，实现后 types.ts 当真相校。</p>',14)])])}const h=o(r,[["render",a]]);export{A as __pageData,h as default};
